package pricing

import (
	"context"
	_ "embed"
	"strings"
	"sync"
	"sync/atomic"
	"time"

	"github.com/router-for-me/CLIProxyAPI/v8/internal/config"
	"github.com/router-for-me/CLIProxyAPI/v8/internal/registry"
	"github.com/router-for-me/CLIProxyAPI/v8/sdk/cliproxy/usage"
	log "github.com/sirupsen/logrus"
)

// DefaultCatalogURL is the default remote price catalog (models.dev, MIT).
const DefaultCatalogURL = "https://models.dev/api.json"

// embeddedSnapshot is a compact models.dev subset generated by cmd/proxx_gen_pricing.
//
//go:embed snapshot.json
var embeddedSnapshot []byte

type state struct {
	disabled         bool
	overrideUpstream bool
	costHeaders      []string
	entries          []configEntry
}

type catalogInfo struct {
	catalog   *Catalog
	source    string
	updatedAt time.Time
}

var (
	stateValue   atomic.Pointer[state]
	catalogValue atomic.Pointer[catalogInfo]
	// configuredSource is the display name of the active catalog source.
	configuredSource atomic.Value
	installOnce      sync.Once
	updater          = registry.NewPriceCatalogUpdater(embeddedSnapshot, []string{DefaultCatalogURL}, ValidateCatalog, publishCatalog)
	nowFunc          = time.Now
)

func currentState() *state { return stateValue.Load() }

func currentCatalog() *Catalog {
	if info := catalogValue.Load(); info != nil {
		return info.catalog
	}
	return nil
}

func publishCatalog(data []byte) error {
	c, err := ParseCatalog(data)
	if err != nil {
		return err
	}
	source, _ := configuredSource.Load().(string)
	catalogValue.Store(&catalogInfo{catalog: c, source: source, updatedAt: nowFunc().UTC()})
	log.WithFields(log.Fields{"models": c.Len(), "source": source}).Debug("proxx: price catalog updated")
	return nil
}

func loadEmbedded() {
	c, err := ParseCatalog(embeddedSnapshot)
	if err != nil {
		log.WithError(err).Warn("proxx: embedded price snapshot is invalid")
		return
	}
	catalogValue.Store(&catalogInfo{catalog: c, source: "embed", updatedAt: nowFunc().UTC()})
}

// Configure applies proxx.pricing. It is safe to call on every config reload; an
// unchanged catalog source does not restart the updater. ctx bounds the refresh loop.
func Configure(ctx context.Context, cfg config.ProxxPricingConfig) {
	installOnce.Do(func() { usage.SetCostHook(ApplyCost) })
	headers := make([]string, 0, len(cfg.CostHeaders))
	for _, h := range cfg.CostHeaders {
		if h = strings.TrimSpace(h); h != "" {
			headers = append(headers, h)
		}
	}
	stateValue.Store(&state{
		disabled:         cfg.Disabled,
		overrideUpstream: cfg.OverrideUpstream,
		costHeaders:      headers,
		entries:          buildConfigEntries(cfg.Models),
	})

	source := strings.TrimSpace(cfg.Catalog)
	if cfg.Disabled {
		source = "disabled"
	}
	display := source
	switch {
	case source == "" && registry.LocalModelCatalogs():
		display = "embed"
	case source == "":
		display = DefaultCatalogURL
	}
	configuredSource.Store(display)
	if source == "disabled" {
		catalogValue.Store(&catalogInfo{source: "disabled", updatedAt: nowFunc().UTC()})
	} else if info := catalogValue.Load(); info == nil || info.catalog == nil {
		// The embedded snapshot serves lookups until (and unless) a remote refresh succeeds.
		loadEmbedded()
	}
	if ctx != nil {
		updater.Configure(ctx, source)
	}
}

// CatalogStatus describes the active price catalog.
type CatalogStatus struct {
	Source           string
	UpdatedAt        time.Time
	Models           int
	OverrideUpstream bool
	Disabled         bool
}

// Status returns the active catalog source, last update time and config flags.
func Status() CatalogStatus {
	out := CatalogStatus{}
	if info := catalogValue.Load(); info != nil {
		out.Source = info.source
		out.UpdatedAt = info.updatedAt
		out.Models = info.catalog.Len()
	}
	if st := currentState(); st != nil {
		out.OverrideUpstream = st.overrideUpstream
		out.Disabled = st.disabled
	}
	return out
}

// Lookup returns the resolved price for model served by provider (config, then catalog).
func Lookup(provider, model string) (Match, bool) {
	st := currentState()
	if st == nil || st.disabled {
		return Match{}, false
	}
	return lookup(st.entries, currentCatalog(), provider, model, "")
}
